const body = $input.first().json.body;
const rawText = body.user_message || '';
const chatId = body.chat_id || '';

// Extract product URL
const urlMatch = rawText.match(/https?:\/\/[^\s]+/);
const productUrl = urlMatch ? urlMatch[0] : '';

// Extract handle from URL (segment after /products/)
let handle = '';
if (productUrl.includes('/products/')) {
  handle = productUrl.split('/products/')[1].split(/[?&#]/)[0].trim();
}

// Extract variant name from parentheses on the product line
const variantMatch = rawText.match(/\(([^)]+)\)\s*(?:\r?\n|$)/);
const variantTitle = variantMatch ? variantMatch[1].trim() : '';

return [{
  json: {
    chatId,
    handle,
    variantTitle,
    rawText
  }
}];

const parsed = $('Parse WhatsApp Message').first().json;
const response = $input.first().json;

const product = response.data && response.data.productByHandle;

let replyMessage;
if (!product) {
  replyMessage = "Sorry, we couldn't find that product. Please share the product link again or contact us directly.";
} else {
  const variants = product.variants.edges.map(e => e.node);
  let variant = variants.find(v => v.title.toLowerCase() === parsed.variantTitle.toLowerCase());
  if (!variant) variant = variants[0];

  const inStock = variant.availableForSale && variant.inventoryQuantity > 0;

  if (inStock) {
    replyMessage = `Good news! "${product.title}" (${variant.title}) is in stock.\n\nWe'll get your order confirmed shortly. Would you like to proceed with payment?`;
  } else {
    replyMessage = `Sorry, "${product.title}" (${variant.title}) is currently out of stock.\n\nWould you like us to notify you when it's back, or see similar sarees?`;
  }
}

return [{
  json: {
    chatId: parsed.chatId,
    replyMessage
  }
}];

const body = $("Webhook").first().json.body || {};
const rawMessage = body.user_message || '';
const chatId = body.chat_id || '';
const firstName = body.first_name || '';
const replyToMessageId = body.reply_message_id || null;

// Pulls a "Label: value" line out of the message text
function extractField(text, label) {
  const regex = new RegExp(`^${label}:\\s*(.+)$`, 'm');
  const match = text.match(regex);
  return match ? match[1].trim() : null;
}

// Splits "INR 7,499.00" into { currency: "INR", amount: 7499 }
function splitMoney(str) {
  if (!str) return { currency: null, amount: null };
  const match = str.match(/^([A-Z]{3})\s+([\d,]+\.\d{2})$/);
  if (!match) return { currency: null, amount: null };
  return {
    currency: match[1],
    amount: parseFloat(match[2].replace(/,/g, ''))
  };
}

// --- 1. Button click check ---
const buttonMatch = rawMessage.match(/^#Button Reply#(.+)$/);

if (buttonMatch) {
  const buttonTitle = buttonMatch[1].trim();
  // "Confirm Order" -> "btn_confirm_order"
  const buttonSlug = buttonTitle.toLowerCase().replace(/\s+/g, '_');

  return [{
    json: {
      messageType: `btn_${buttonSlug}`,
      chatId,
      firstName,
      rawMessage,
      buttonTitle,
      replyToMessageId
    }
  }];
}

// --- 2. Order check ---
const variantIdRaw = extractField(rawMessage, 'Variant ID');

const isOrderMessage =
  /^NEW ORDER/i.test(rawMessage.trim()) &&
  variantIdRaw &&
  /^\d+$/.test(variantIdRaw);

if (isOrderMessage) {
  const unitPrice = splitMoney(extractField(rawMessage, 'Unit Price'));
  const total = splitMoney(extractField(rawMessage, 'Total'));
  const quantityRaw = extractField(rawMessage, 'Quantity');

  return [{
    json: {
      messageType: 'order',
      chatId,
      firstName,
      rawMessage,
      product: extractField(rawMessage, 'Product'),
      variantTitle: extractField(rawMessage, 'Variant'),
      variantId: variantIdRaw,
      quantity: quantityRaw ? parseInt(quantityRaw, 10) : null,
      currency: unitPrice.currency,
      unitPrice: unitPrice.amount,
      total: total.amount,
      productLink: extractField(rawMessage, 'Link')
    }
  }];
}

// --- 3. Normal message ---
return [{
  json: {
    messageType: 'normal',
    chatId,
    firstName,
    rawMessage
  }
}];

// Pulls the parsed WhatsApp message from earlier in the workflow.
// ⚠️ Change 'Parse & Classify Message' below to match whatever you
// actually named that Code node in your workflow.
const parsed = $('Parse & Classify Message').first().json;

// If it wasn't an order message, just pass it through untouched
if (parsed.messageType !== 'order') {
  return [{
    json: {
      ...parsed,
      stockChecked: false
    }
  }];
}

const targetVariantId = String(parsed.variantId);

// This node's own input = all products from the Shopify "Get many products" node
const products = $input.all().map(item => item.json);

let foundProduct = null;
let foundVariant = null;

for (const product of products) {
  const variants = product.variants || [];
  const match = variants.find(v => String(v.id) === targetVariantId);
  if (match) {
    foundProduct = product;
    foundVariant = match;
    break;
  }
}

if (!foundVariant) {
  return [{
    json: {
      ...parsed,
      stockChecked: true,
      found: false,
      inStock: false
    }
  }];
}

// inventory_management === null means Shopify isn't tracking stock for
// this variant at all — in that case it's always treated as orderable.
const isTracked = foundVariant.inventory_management !== null && foundVariant.inventory_management !== undefined;
const inventoryQuantity = foundVariant.inventory_quantity ?? 0;
const allowsOverselling = foundVariant.inventory_policy === 'continue';

const inStock = !isTracked || inventoryQuantity > 0 || allowsOverselling;
const enoughForOrder = inStock && (!isTracked || allowsOverselling || inventoryQuantity >= parsed.quantity);

return [{
  json: {
    ...parsed,
    stockChecked: true,
    found: true,
    inStock,
    enoughForOrder,
    availableQuantity: inventoryQuantity,
    matchedProductTitle: foundProduct.title,
    matchedVariantTitle: foundVariant.title,
    matchedVariantPrice: foundVariant.price
  }
}];

